269	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
270	
271	    /**
272	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
273	     * code are kept when present; otherwise country code '+61' is assumed and a single
274	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
275	     * stripped. The result must be a '+' followed by 8 to 15 digits.
276	     * Returns {@code null} when the number cannot form a valid E.164 value.
277	     */
278	    private static String normalizeTelephone(String telephone) {
279	        if (telephone == null) {
280	            return null;
281	        }
282	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
283	        String e164;
284	        if (cleaned.startsWith("+")) {
285	            e164 = cleaned;
286	        } else {
287	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
288	            e164 = "+61" + national;
289	        }
290	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
291	    }
292	
293	    /**
294	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
295	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
296	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
297	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
298	     */
299	    private String generateCustomerCode(String city, String lastName) {
300	        String city3 = firstThreeLetters(city);
301	        String last3 = firstThreeLetters(lastName);
302	        int sequence = countOwnersInCity(city) + 1;
303	        return String.format("%s-%s-%04d", city3, last3, sequence);
304	    }
305	
306	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
307	    private static String firstThreeLetters(String value) {
308	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
309	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
310	    }
311	
312	    /**
313	     * The number of existing owners registered in {@code city}, compared case-insensitively
314	     * with collapsed whitespace.
315	     */
316	    private int countOwnersInCity(String city) {
317	        String normalized = normalizeHouseholdField(city);
318	        return (int) this.clinicService.findAllOwners().stream()
319	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
320	            .count();
321	    }
322	
323	    /**
324	     * The effective registration date to store for a new owner: the date supplied on the request
325	     * when present, otherwise the current server date, in either case rolled forward to a business
326	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
327	     * This single point of resolution is what every registration-date-derived value (the stored
328	     * date, the membership number's year segment, the per-day create-limit) is computed from.
329	     */
330	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
331	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
332	        return toBusinessDay(date);
333	    }
334	
335	    /**
336	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
337	     * following Monday; a weekday is returned unchanged.
338	     */
339	    private static LocalDate toBusinessDay(LocalDate date) {
340	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
341	            date = date.plusDays(1);
342	        }
343	        return date;
344	    }
345	
346	    /**
347	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
348	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
349	     */
