351	        String yy = String.format("%02d", registrationDate.getYear() % 100);
352	        return customerCode + "-M" + yy;
353	    }
354	
355	    /**
356	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
357	     * last name, compared case-insensitively.
358	     */
359	    private int countNamesakes(Owner owner) {
360	        String firstName = normalizeHouseholdField(owner.getFirstName());
361	        String lastName = normalizeHouseholdField(owner.getLastName());
362	        return (int) this.clinicService.findAllOwners().stream()
363	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
364	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
365	            .count();
366	    }
367	
368	    /**
369	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
370	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
371	     * unusually high daily signup volume.
372	     */
373	    private boolean isBulkSignupWarning() {
374	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
375	    }
376	
377	    /** The number of existing owners whose registration date is {@code date}. */
378	    private int countOwnersRegisteredOn(LocalDate date) {
379	        return (int) this.clinicService.findAllOwners().stream()
380	            .filter(existing -> date.equals(existing.getRegistrationDate()))
381	            .count();
382	    }
383	
384	    /** Whether any existing owner already uses the given (E.164) telephone number. */
385	    private boolean isTelephoneInUse(String telephone) {
386	        return this.clinicService.findAllOwners().stream()
387	            .map(Owner::getTelephone)
388	            .filter(existing -> existing != null)
389	            .map(OwnerRestControllerV1::normalizeTelephone)
390	            .filter(existing -> existing != null)
391	            .anyMatch(telephone::equals);
392	    }
393	
394	    /** Common street-type abbreviations expanded during address normalization. */
395	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
396	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
397	
398	    /**
399	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
400	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
401	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
402	     * string when {@code address} is null or blank after normalization.
403	     */
404	    private static String normalizeAddress(String address) {
405	        if (address == null) {
406	            return "";
407	        }
408	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
409	        if (collapsed.isEmpty()) {
410	            return "";
411	        }
412	        StringBuilder sb = new StringBuilder(collapsed.length());
413	        for (String token : collapsed.split(" ")) {
414	            if (sb.length() > 0) {
415	                sb.append(' ');
416	            }
417	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
418	        }
419	        return sb.toString();
420	    }
421	
422	    /**
423	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
424	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
425	     */
426	    private static String normalizeHouseholdField(String value) {
427	        if (value == null) {
428	            return "";
429	        }
430	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
431	    }
432	
433	    /**
434	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
435	     * same address compared case-insensitively with collapsed whitespace.
436	     */
437	    private List<Owner> findHousemates(Owner owner) {
438	        String lastName = normalizeHouseholdField(owner.getLastName());
439	        String address = normalizeHouseholdField(owner.getAddress());
440	        return this.clinicService.findAllOwners().stream()
441	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
442	                && normalizeHouseholdField(existing.getAddress()).equals(address))
443	            .toList();
444	    }
445	
446	    /**
447	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
448	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
449	     */
450	    private boolean isHouseholdInUse(Owner owner) {
451	        return !findHousemates(owner).isEmpty();
452	    }
453	
454	    /**
