456	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
457	     * deterministically from those normalized fields so housemates always resolve to the same value,
458	     * regardless of registration order.
459	     */
460	    private static String householdId(Owner owner) {
461	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
462	            + normalizeHouseholdField(owner.getAddress());
463	        try {
464	            byte[] digest = MessageDigest.getInstance("SHA-256")
465	                .digest(key.getBytes(StandardCharsets.UTF_8));
466	            StringBuilder sb = new StringBuilder(24);
467	            for (int i = 0; i < 12; i++) {
468	                sb.append(String.format("%02X", digest[i]));
469	            }
